package pe.edu.upeu.pago.client; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Component; import pe.edu.upeu.pago.dto.*; @Component @RequiredArgsConstructor public class InscripcionClient {private final InscripcionFeignClient feign; public InscripcionDto crearCompra(Long estudianteId,CursoCompraDto c){return feign.crearCompra(new InscripcionFeignClient.CrearCompraRequest(estudianteId,c.id(),c.leccionIds(),c.progresoMinimo(),c.asistenciaMinima(),c.certificadoHabilitado(),c.certificadoCosto()));} public InscripcionDto buscar(Long estudianteId,Long cursoId){return feign.buscar(estudianteId,cursoId);} public InscripcionDto revocar(Long estudianteId,Long cursoId){return feign.revocar(estudianteId,cursoId);} public CertificadoInscripcionDto certificado(Long id){return feign.certificado(id);} public CertificadoInscripcionDto confirmarPagoCertificado(Long id){return feign.confirmarPagoCertificado(id);} }
